static std::string g_prog;
static long long g_startTime = 0;
static std::mutex g_coutMutex;

// ---------- Usage / help ----------
static std::vector<std::string> wrapUsage(const std::string &prog) {
    const std::string usage =
        "[-i <path to directory>] [-s <positive integer>] [-d <a string containing two space-seprated positive integers>] "
        "[-n <{1,2,3,4,5,6}>] [-r] [-t] [-o] [-q] [--] [--version] [-h] <Array of strings> ...";
    std::string prefix = "   " + prog + "  ";
    std::string indent(prefix.size(), ' ');
    const int maxWidth = 75;
    std::vector<std::string> lines;
    // Word wrap the usage text.
    std::vector<std::string> words;
    {
        std::string cur;
        for (char c : usage) {
            if (c == ' ') { if (!cur.empty()) { words.push_back(cur); cur.clear(); } }
            else cur.push_back(c);
        }
        if (!cur.empty()) words.push_back(cur);
    }
    std::string line = prefix;
    bool firstInLine = true;
    for (size_t wi = 0; wi < words.size(); ++wi) {
        const std::string &w = words[wi];
        std::string add = firstInLine ? w : (" " + w);
        if ((int)(line.size() + add.size()) > maxWidth && !firstInLine) {
            lines.push_back(line);
            line = indent + w;
            firstInLine = false;
        } else if ((int)(line.size() + add.size()) > maxWidth && firstInLine && (int)(indent.size() + w.size()) > maxWidth) {
            // Single very long word: hard-split it across lines.
            std::string rest = w;
            std::string curLine = line;
            while ((int)(curLine.size() + rest.size()) > maxWidth) {
                int room = maxWidth - (int)curLine.size();
                if (room < 1) room = 1;
                curLine += rest.substr(0, room);
                rest = rest.substr(room);
                lines.push_back(curLine);
                curLine = indent;
            }
            line = curLine + rest;
            firstInLine = false;
        } else {
            line += add;
            firstInLine = false;
        }
    }
    lines.push_back(line);
    return lines;
}

static std::string usageBlock(const std::string &prog) {
    auto lines = wrapUsage(prog);
    std::string out;
    for (auto &l : lines) { out += l; out += "\n"; }
    return out;
}

static void printHelp() {
    std::cout << "\nUSAGE: \n\n";
    std::cout << usageBlock(g_prog);
