        "     Start commands for bots.\n";
    std::cout << "\n\n   Halite Game Environment\n\n";
    std::cout.flush();
    std::exit(0);
}

static void printVersion() {
    std::cout << "\n" << g_prog << "  version: 1.2\n\n";
    std::cout.flush();
    std::exit(0);
}

[[noreturn]] static void parseError(const std::string &argDisplay, const std::string &msg) {
    std::cerr << "PARSE ERROR: Argument: " << argDisplay << "\n";
    std::cerr << "             " << msg << "\n";
    std::cerr << "\n";
    std::cerr << "Brief USAGE: \n";
    std::cerr << usageBlock(g_prog);
    std::cerr << "\n";
    std::cerr << "For complete USAGE and HELP type: \n";
    std::cerr << "   " << g_prog << " --help\n";
    std::cerr << "\n";
    std::cerr.flush();
    std::exit(1);
}

// ---------- Config & parsing ----------
struct Dimension {
    int width = 0;
    int height = 0;
};
static std::istream &operator>>(std::istream &is, Dimension &d) {
    is >> d.width >> d.height;
    return is;
}

struct Config {
    bool quiet = false;
    bool noreplay = false;
    bool ignoreTimeouts = false;
    bool overrideFlag = false;
    bool seedSet = false;
    unsigned int seed = 0;
    bool dimsSet = false;
    Dimension dims;
    int nplayers = 1;
    bool nplayersSet = false;
    bool replayDirSet = false;
    std::string replayDir = ".";
    std::vector<std::string> positional;
};

struct ArgMeta {
    char shortName;
    std::string longName;
    std::string display;
    int kind; //0 string,1 uint,2 dim,3 int
};

template <typename T>
static T extractValue(const std::string &str, const ArgMeta &meta) {
    std::stringstream extractor(str);
    T value;
    extractor >> value;
    if (extractor.fail()) {
        parseError(meta.display, "Couldn't read argument value from string '" + str + "'");
    }
    if (!extractor.eof()) {
        T second;
        extractor >> second;
        if (extractor.fail()) {
            parseError(meta.display, "Couldn't read argument value from string '" + str + "'");
        } else {
            parseError(meta.display, "More than one valid value parsed from string '" + str + "'");
        }
    }
    return value;
}

static Config parseArgs(int argc, char *argv[]) {
    Config cfg;
    bool seenSeed = false, seenDims = false, seenN = false, seenReplayDir = false;
    bool seenR = false, seenT = false, seenO = false, seenQ = false, seenH = false;
    bool ignoreRest = false;
    std::vector<std::string> args;
    for (int i = 1; i < argc; ++i) args.push_back(argv[i] ? argv[i] : "");

    auto metaFor = [](char c) -> ArgMeta {
        switch (c) {
            case 'i': return {'i', "replaydirectory", "-i (--replaydirectory)", 0};
            case 's': return {'s', "seed", "-s (--seed)", 1};
            case 'd': return {'d', "dimensions", "-d (--dimensions)", 2};
            case 'n': return {'n', "nplayers", "-n (--nplayers)", 3};
        }
        return {0, "", "", -1};
    };
    auto switchDisplay = [](char c) -> std::string {
        switch (c) {
            case 'r': return "-r (--noreplay)";
            case 't': return "-t (--timeout)";
            case 'o': return "-o (--override)";
            case 'q': return "-q (--quiet)";
            case 'h': return "-h (--help)";
        }
        return std::string("-") + c;
    };
    auto setSwitch = [&](char c) {
        switch (c) {
            case 'r': cfg.noreplay = true; break;
            case 't': cfg.ignoreTimeouts = true; break;
            case 'o': cfg.overrideFlag = true; break;
            case 'q': cfg.quiet = true; break;
        }
    };
    auto switchSeen = [&](char c) -> bool {
        switch (c) {
            case 'r': return seenR;
            case 't': return seenT;
            case 'o': return seenO;
            case 'q': return seenQ;
            case 'h': return seenH;
        }
        return false;
    };
    auto markSwitchSeen = [&](char c) {
        switch (c) {
            case 'r': seenR = true; break;
            case 't': seenT = true; break;
            case 'o': seenO = true; break;
            case 'q': seenQ = true; break;
            case 'h': seenH = true; break;
        }
    };

    for (size_t idx = 0; idx < args.size();) {
        std::string tok = args[idx];
        if (ignoreRest) { cfg.positional.push_back(tok); ++idx; continue; }
        if (tok == "--" || tok == "--ignore_rest") { ignoreRest = true; ++idx; continue; }
        if (tok == "--help" || tok == "-h") printHelp();
        if (tok == "--version") printVersion();

        // Exact value arguments (short or long).
        char vchar = 0;
        bool isValueTok = false;
        if (tok == "-i" || tok == "--replaydirectory") { vchar = 'i'; isValueTok = true; }
        else if (tok == "-s" || tok == "--seed") { vchar = 's'; isValueTok = true; }
        else if (tok == "-d" || tok == "--dimensions") { vchar = 'd'; isValueTok = true; }
        else if (tok == "-n" || tok == "--nplayers") { vchar = 'n'; isValueTok = true; }
        if (isValueTok) {
            ArgMeta meta = metaFor(vchar);
            bool already = (vchar == 'i' && seenReplayDir) || (vchar == 's' && seenSeed) ||
                           (vchar == 'd' && seenDims) || (vchar == 'n' && seenN);
            if (already) parseError(meta.display, "Argument already set!");
            if (idx + 1 >= args.size()) parseError(meta.display, "Missing a value for this argument!");
            std::string val = args[idx + 1];
            if (vchar == 'i') { cfg.replayDir = val; cfg.replayDirSet = true; seenReplayDir = true; }
            else if (vchar == 's') { cfg.seed = extractValue<unsigned int>(val, meta); cfg.seedSet = true; seenSeed = true; }
            else if (vchar == 'd') { cfg.dims = extractValue<Dimension>(val, meta); cfg.dimsSet = true; seenDims = true; }
            else if (vchar == 'n') { cfg.nplayers = extractValue<int>(val, meta); cfg.nplayersSet = true; seenN = true; }
            idx += 2;
            continue;
        }
        // Exact switch arguments.
        char schar = 0;
        bool isSwitchTok = false;
        if (tok == "-r" || tok == "--noreplay") { schar = 'r'; isSwitchTok = true; }
        else if (tok == "-t" || tok == "--timeout") { schar = 't'; isSwitchTok = true; }
        else if (tok == "-o" || tok == "--override") { schar = 'o'; isSwitchTok = true; }
        else if (tok == "-q" || tok == "--quiet") { schar = 'q'; isSwitchTok = true; }
        if (isSwitchTok) {
            if (switchSeen(schar)) parseError(switchDisplay(schar), "Argument already set!");
            markSwitchSeen(schar); setSwitch(schar);
            ++idx; continue;
        }
        // Long unknown tokens and single dash tokens are positional (unmatched).
        if (tok.size() >= 2 && tok[0] == '-' && tok[1] == '-') { cfg.positional.push_back(tok); ++idx; continue; }
        if (tok.size() <= 2 && !(tok.size() == 2 && tok[0] == '-')) { cfg.positional.push_back(tok); ++idx; continue; }
        if (tok.size() == 2) { cfg.positional.push_back(tok); ++idx; continue; }
        // Tokens starting with '-' and longer than 2 chars: cluster or positional.
        if (tok.size() > 2 && tok[0] == '-') {
            char first = tok[1];
            if (first == 'i' || first == 's' || first == 'd' || first == 'n') {
                bool containsSwitch = false;
                for (size_t k = 2; k < tok.size(); ++k) {
                    char c = tok[k];
                    if (c == 'r' || c == 't' || c == 'o' || c == 'q' || c == 'h') containsSwitch = true;
                }
                if (containsSwitch) {
                    std::string disp = tok;
                    for (size_t k = 1; k < disp.size(); ++k) {
                        char c = disp[k];
                        if (c == 'r' || c == 't' || c == 'o' || c == 'q' || c == 'h') disp[k] = '\a';
                    }
                    parseError(disp, "Couldn't find match for argument");
                }
                cfg.positional.push_back(tok); ++idx; continue;
            }
            // Cluster of switch characters.
            bool hasUnknown = false;
            bool helpInCluster = false;
            for (size_t k = 1; k < tok.size(); ++k) {
                char c = tok[k];
                if (c == 'r' || c == 't' || c == 'o' || c == 'q' || c == 'h') {
                    if (switchSeen(c) || (c == 'h' && helpInCluster)) {
                        parseError(switchDisplay(c), "Argument already set!");
                    }
                    if (c == 'h') helpInCluster = true;
                    markSwitchSeen(c); setSwitch(c);
                } else {
                    hasUnknown = true;
                }
            }
            if (hasUnknown) {
                std::string disp = tok;
                for (size_t k = 1; k < disp.size(); ++k) {
                    char c = disp[k];
                    if (c == 'r' || c == 't' || c == 'o' || c == 'q' || c == 'h') disp[k] = '\a';
                }
                parseError(disp, "Couldn't find match for argument");
            }
            if (helpInCluster) printHelp();
            ++idx; continue;
        }
        cfg.positional.push_back(tok); ++idx;
    }
    return cfg;
}

// ---------- Utilities ----------
static bool writeAllFd(int fd, const std::string &data) {
    size_t off = 0;
    while (off < data.size()) {
        ssize_t n = ::write(fd, data.data() + off, data.size() - off);
        if (n > 0) off += (size_t)n;
        else if (n < 0 && errno == EINTR) continue;
        else return false;
    }
    return true;
}

static std::string jsonEscape(const std::string &s) {
    std::string out;
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    char buf[8]; std::snprintf(buf, sizeof(buf), "\\u%04x", c); out += buf;
                } else out.push_back((char)c);
        }
    }
    return out;
}

static std::string truncate30(const std::string &s) {
    if (s.size() > 30) return s.substr(0, 30);
    return s;
}

// ---------- Game structures ----------
struct Player {
    int id = 0; // 1-based
    std::string command;
    std::string botName;      // truncated bot-sent name
    std::string finalName;    // override or botName (truncated)
    std::string log;
    std::string logFilename;
    bool errored = false;
    bool processRunning = false;
    pid_t pid = -1;
    int writeFd = -1;
    int readFd = -1;
    std::string inBuffer; // buffered unprocessed bytes from bot
    bool inEof = false;
    int lastFrameAlive = 0;
    long long totalTerritory = 0;
    int rank = 0;
    // per-turn data
    std::string turnResponse;
    bool turnError = false;
    bool turnInvalid = false;
    bool turnHasResponse = false;
};

struct GameMap {
    int W = 0, H = 0;
    std::vector<int> production; // size W*H
    std::vector<int> owner;
    std::vector<int> strength;
};

// A symmetry transform represented as a permutation of cell indices.
struct Symmetry {
    std::vector<std::vector<int>> perms; // list of permutations, first identity
    std::vector<std::pair<int,int>> startsByPlayer; // will be filled per intended player order
};

static int cellIndex(int x, int y, int W) { return y * W + x; }

// ---------- Map generation ----------
struct GeneratedMap {
    GameMap map;
    std::vector<std::pair<int,int>> starts; // intended-player order
};

static GeneratedMap generateMap(int reqW, int reqH, int intendedPlayers, unsigned int seed, int actualPlayers) {
    std::mt19937 rng(seed);
    int P = intendedPlayers;
    int W = reqW, H = reqH;

    // Layout bookkeeping.
    enum class Kind { Single, Grid, HStrips, VStrips };
    Kind kind = Kind::Single;
    int cols = 1, rows = 1;
    int tileW = reqW, tileH = reqH;
    int shiftStep = 0; // in cells for strips, per strip
    // Transforms as coordinate functions are captured via permutations after dims known.
    std::vector<std::function<std::pair<int,int>(int,int)>> transforms;

    if (P == 1) {
        W = reqW; H = reqH;
        kind = Kind::Single;
    } else if (P == 4 || P == 6) {
        kind = Kind::Grid;
        std::vector<std::pair<int,int>> factors;
        if (P == 4) factors = {{2,2}};
        else factors = {{2,3},{3,2}};
        auto chosen = factors[(size_t)(rng() % (unsigned)factors.size())];
        cols = chosen.first; rows = chosen.second;
        int extraAxis; // 0 width, 1 height
        if (cols == 2 && rows == 3) extraAxis = 0;
        else if (cols == 3 && rows == 2) extraAxis = 1;
        else extraAxis = (int)(rng() % 2);
        if (extraAxis == 0) {
            int tw0 = (cols > 0 ? W / cols : W);
            tileW = tw0 - (P > 0 ? (tw0 % P) : 0);
            W = cols * tileW;
            tileH = (rows > 0 ? H / rows : H);
            H = rows * tileH;
        } else {
            tileW = (cols > 0 ? W / cols : W);
            W = cols * tileW;
            int th0 = (rows > 0 ? H / rows : H);
            tileH = th0 - (P > 0 ? (th0 % P) : 0);
            H = rows * tileH;
        }
    } else {
        // Prime number of players (2,3,5): strips.
        int orientation = (int)(rng() % 2); // 0 horizontal, 1 vertical
        int shift = (int)(rng() % (unsigned)P);
        W = reqW - (P > 0 ? (reqW % P) : 0);
        H = reqH - (P > 0 ? (reqH % P) : 0);
        if (orientation == 0) {
            kind = Kind::HStrips;
            cols = 1; rows = P;
            tileW = W; tileH = (P > 0 ? H / P : H);
            shiftStep = (P > 0 ? (W / P) * shift : 0);
        } else {
            kind = Kind::VStrips;
            cols = P; rows = 1;
            tileW = (P > 0 ? W / P : W); tileH = H;
            shiftStep = (P > 0 ? (H / P) * shift : 0);
        }
    }

    if (W <= 0 || H <= 0) {
        std::cout.flush(); std::cerr.flush();
        ::raise(SIGSEGV);
        _Exit(139);
    }
    // For unusually huge dimensions that arrive via unsigned-short wrap in the
    // original parameter types, mimic a crash rather than attempting an
    // enormous allocation.
    if (W > 10000 || H > 10000) {
        std::cout.flush(); std::cerr.flush();
        ::raise(SIGSEGV);
        _Exit(139);
    }

    // Build transforms as functions on coordinates (valid now that W,H known).
    if (kind == Kind::Single) {
        transforms.push_back([](int x, int y){ return std::make_pair(x,y); });
    } else if (kind == Kind::Grid) {
        // Horizontal generator: mirror in x. Vertical: mirror if 2 rows else translate by tile.
        for (int ry = 0; ry < rows; ++ry) {
            for (int fx = 0; fx < 2; ++fx) {
                // To avoid duplicate full sets when cols>2 horizontally we use translations instead below.
                (void)ry; (void)fx;
            }
        }
        transforms.clear();
        if (cols == 2 && rows == 2) {
            transforms.push_back([](int x,int y){ return std::make_pair(x,y); });
            transforms.push_back([W](int x,int y){ return std::make_pair(W-1-x,y); });
            transforms.push_back([H](int x,int y){ return std::make_pair(x,H-1-y); });
            transforms.push_back([W,H](int x,int y){ return std::make_pair(W-1-x,H-1-y); });
        } else if (cols == 2) {
            // mirror x, translate y by tileH
            for (int k = 0; k < rows; ++k) {
                transforms.push_back([k,tileH = tileH,H](int x,int y){ return std::make_pair(x, (y + k*tileH) % H); });
                transforms.push_back([k,tileH = tileH,W,H](int x,int y){ return std::make_pair(W-1-x, (y + k*tileH) % H); });
            }
        } else if (rows == 2) {
            // translate x by tileW, mirror y
            for (int k = 0; k < cols; ++k) {
                transforms.push_back([k,tileW = tileW,W](int x,int y){ return std::make_pair((x + k*tileW) % W, y); });
                transforms.push_back([k,tileW = tileW,W,H](int x,int y){ return std::make_pair((x + k*tileW) % W, H-1-y); });
            }
        } else {
            transforms.push_back([](int x,int y){ return std::make_pair(x,y); });
        }
    } else if (kind == Kind::HStrips) {
        for (int k = 0; k < P; ++k) {
            transforms.push_back([k, shiftStep, tileH, W, H](int x,int y){
                return std::make_pair( ((x + k*shiftStep) % W + W) % W, (y + k*tileH) % H );
            });
        }
    } else if (kind == Kind::VStrips) {
        for (int k = 0; k < P; ++k) {
            transforms.push_back([k, shiftStep, tileW, W, H](int x,int y){
                return std::make_pair( (x + k*tileW) % W, ((y + k*shiftStep) % H + H) % H );
            });
        }
    }
    // Deduplicate transforms by their effect on a generic basis: keep unique permutations later.
    // Generate fields.
    int N = W * H;
    std::vector<double> prodD(N), strD(N);
    auto uni = [&]() {
        // A double in (0,1).
        return ( (double)rng() + 0.5 ) / 4294967296.0;
    };
    for (int i = 0; i < N; ++i) { double u = uni(); prodD[i] = 16.0 * u * u * u; }
    for (int i = 0; i < N; ++i) { double u = uni(); strD[i] = 256.0 * u * u * u; }
    auto smooth = [&](std::vector<double> v) {
        const int passes = 10;
        std::vector<double> cur = v, nxt = v;
        for (int p = 0; p < passes; ++p) {
            for (int y = 0; y < H; ++y) {
                for (int x = 0; x < W; ++x) {
                    int xm = (x - 1 + W) % W, xp = (x + 1) % W;
                    int ym = (y - 1 + H) % H, yp = (y + 1) % H;
                    double sum = cur[cellIndex(x,y,W)] + cur[cellIndex(xm,y,W)] + cur[cellIndex(xp,y,W)] + cur[cellIndex(x,ym,W)] + cur[cellIndex(x,yp,W)];
                    nxt[cellIndex(x,y,W)] = sum / 5.0;
                }
            }
            cur.swap(nxt);
            if (W == 1 && H == 1) break;
        }
        return cur;
    };
    prodD = smooth(prodD);
    strD = smooth(strD);
    std::vector<int> prod(N), strg(N), owner(N, 0);
    for (int i = 0; i < N; ++i) {
        int pv = (int)std::lround(prodD[i]); if (pv < 0) pv = 0; if (pv > 15) pv = 15; prod[i] = pv;
        int sv = (int)std::lround(strD[i]); if (sv < 0) sv = 0; if (sv > 255) sv = 255; strg[i] = sv;
    }
    // Symmetrise by copying from canonical orbit representatives.
    if (P > 1 && transforms.size() > 1) {
        std::vector<int> prodSym = prod, strSym = strg;
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                int best = cellIndex(x,y,W);
                for (auto &fn : transforms) {
                    auto q = fn(x,y);
                    int idxx = cellIndex(q.first, q.second, W);
                    if (idxx < best) best = idxx;
                }
                prodSym[cellIndex(x,y,W)] = prod[best];
                strSym[cellIndex(x,y,W)] = strg[best];
            }
        }
        prod = prodSym; strg = strSym;
    }

    // Starting positions.
    std::vector<std::pair<int,int>> starts;
    if (kind == Kind::Single) {
        starts.push_back({W/2, H/2});
    } else if (kind == Kind::Grid) {
        int cx = tileW / 2, cy = tileH / 2;
        std::set<std::pair<int,int>> uniq;
        for (auto &fn : transforms) {
            auto q = fn(cx, cy);
            uniq.insert(q);
        }
        // Sort by (y,x) for grid order.
        std::vector<std::pair<int,int>> pts(uniq.begin(), uniq.end());
        std::sort(pts.begin(), pts.end(), [](const std::pair<int,int>&a, const std::pair<int,int>&b){
            if (a.second != b.second) return a.second < b.second;
            return a.first < b.first;
        });
        starts = pts;
    } else if (kind == Kind::HStrips) {
        int bx = W/2, by = tileH/2;
        for (auto &fn : transforms) starts.push_back(fn(bx, by));
    } else if (kind == Kind::VStrips) {
        int bx = tileW/2, by = H/2;
        for (auto &fn : transforms) starts.push_back(fn(bx, by));
    }
    // If the orbit produced fewer points than intended (degenerate tiny maps),
    // fall back to distinct cells scanning row-major.
    if ((int)starts.size() < P) {
        std::set<std::pair<int,int>> have(starts.begin(), starts.end());
        for (int y = 0; y < H && (int)starts.size() < P; ++y)
            for (int x = 0; x < W && (int)starts.size() < P; ++x) {
                auto pt = std::make_pair(x,y);
                if (!have.count(pt)) { starts.push_back(pt); have.insert(pt); }
            }
    }
    // Assign owners for actual players only.
    int toAssign = std::min<int>(actualPlayers, (int)starts.size());
    // In multiplayer, actual == intended; in single-player mode, only player 1.
    for (int i = 0; i < toAssign; ++i) {
        auto pt = starts[i];
        owner[cellIndex(pt.first, pt.second, W)] = i + 1;
    }

    GeneratedMap out;
    out.map.W = W; out.map.H = H;
    out.map.production = prod;
    out.map.owner = owner;
    out.map.strength = strg;
    out.starts = starts;
    return out;
}

// ---------- Bot I/O ----------
static void killBot(Player &p) {
    if (p.pid > 0) {
        ::kill(p.pid, SIGKILL);
        int status = 0;
        // Reap; the child has been SIGKILLed (or already exited).
        while (::waitpid(p.pid, &status, 0) < 0 && errno == EINTR) {}
        p.pid = -1;
    }
    p.processRunning = false;
}

static void launchBot(Player &p) {
    int inPipe[2];  // engine writes to [1], bot reads [0]
    int outPipe[2]; // bot writes to [1], engine reads [0]
    if (::pipe(inPipe) != 0 || ::pipe(outPipe) != 0) {
        p.pid = -1; return;
    }
#ifdef F_SETPIPE_SZ
    ::fcntl(inPipe[0], F_SETPIPE_SZ, 4096); ::fcntl(inPipe[1], F_SETPIPE_SZ, 4096);
    ::fcntl(outPipe[0], F_SETPIPE_SZ, 4096); ::fcntl(outPipe[1], F_SETPIPE_SZ, 4096);
#endif
    pid_t pid = ::fork();
    if (pid == 0) {
        // Child.
        ::dup2(inPipe[0], STDIN_FILENO);
        ::dup2(outPipe[1], STDOUT_FILENO);
        ::dup2(outPipe[1], STDERR_FILENO);
        ::close(inPipe[0]); ::close(inPipe[1]);
        ::close(outPipe[0]); ::close(outPipe[1]);
        ::execl("/bin/sh", "sh", "-c", p.command.c_str(), (char*)nullptr);
        _Exit(127);
    }
    // Parent.
    ::close(inPipe[0]);
    ::close(outPipe[1]);
    p.pid = pid;
    p.writeFd = inPipe[1];
    p.readFd = outPipe[0];
    p.processRunning = (pid > 0);
}

// Buffered line reading for a player. Returns true if a line was obtained.
struct BotReader {
    // Extracts a line if one is already buffered.
    static bool extract(Player &p, std::string &line) {
        size_t pos = p.inBuffer.find('\n');
        if (pos == std::string::npos) return false;
        line = p.inBuffer.substr(0, pos);
        p.inBuffer.erase(0, pos + 1);
        if (!line.empty() && line.back() == '\r') line.pop_back();
        return true;
    }
    static bool readLineBlocking(Player &p, std::string &line) {
        if (extract(p, line)) return true;
        char buf[4096];
        while (true) {
            ssize_t n = ::read(p.readFd, buf, sizeof(buf));
            if (n > 0) {
                p.inBuffer.append(buf, (size_t)n);
                if (extract(p, line)) return true;
            } else if (n == 0) {
                p.inEof = true;
                // The original blocks forever waiting for a response.
                while (true) ::pause();
            } else {
                if (errno == EINTR) continue;
                p.inEof = true;
                while (true) ::pause();
            }
        }
    }
    struct Outcome {
        bool success = false;
        std::string line;
        std::string partial;
    };
    // timeoutMs < 0 means wait forever (like blocking, but still returns on line).
    static Outcome readLineDeadline(Player &p, long long timeoutMs, std::chrono::steady_clock::time_point start) {
        Outcome out;
        if (extract(p, out.line)) { out.success = true; return out; }
        char buf[4096];
        while (true) {
            long long elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
            long long remaining = (timeoutMs < 0) ? 1000 : (timeoutMs - elapsed);
            if (timeoutMs >= 0 && remaining <= 0) {
                out.success = false; out.partial = p.inBuffer; p.inBuffer.clear(); return out;
            }
            int waitMs = (timeoutMs < 0) ? 1000 : (int)std::min<long long>(remaining, 1000);
            struct pollfd pfd;
            pfd.fd = p.readFd; pfd.events = POLLIN; pfd.revents = 0;
            int r = ::poll(&pfd, 1, waitMs);
            if (r > 0) {
                if (pfd.revents & (POLLIN | POLLHUP | POLLERR)) {
                    ssize_t n = ::read(p.readFd, buf, sizeof(buf));
                    if (n > 0) {
                        p.inBuffer.append(buf, (size_t)n);
                        if (extract(p, out.line)) { out.success = true; return out; }
                    } else if (n == 0) {
                        p.inEof = true;
                        if (timeoutMs < 0) { while (true) ::pause(); }
                        // Wait out the remaining deadline, as the original's
                        // response thread remains blocked.
                        auto now = std::chrono::steady_clock::now();
                        long long rem = timeoutMs - std::chrono::duration_cast<std::chrono::milliseconds>(now - start).count();
                        if (rem > 0) std::this_thread::sleep_for(std::chrono::milliseconds(rem));
                        out.success = false; out.partial = p.inBuffer; p.inBuffer.clear(); return out;
                    }
                } else {
                    if (timeoutMs < 0) continue;
                }
            } else if (r == 0) {
                if (timeoutMs < 0) continue;
                // poll segment timed out; loop will check deadline.
            } else {
                if (errno == EINTR) continue;
                if (timeoutMs < 0) continue;
            }
        }
    }
};

// Frame encoding helpers.
static std::string frameLine(const GameMap &m) {
    std::string out;
    int N = m.W * m.H;
    // Owner runs (flattened).
    int i = 0;
    while (i < N) {
        int j = i;
        while (j < N && m.owner[j] == m.owner[i]) ++j;
        out += std::to_string(j - i);
        out.push_back(' ');
        out += std::to_string(m.owner[i]);
        out.push_back(' ');
        i = j;
    }
    for (int k = 0; k < N; ++k) { out += std::to_string(m.strength[k]); out.push_back(' '); }
    out.push_back('\n');
    return out;
}
static std::string productionLine(const GameMap &m) {
    std::string out;
    for (int v : m.production) { out += std::to_string(v); out.push_back(' '); }
    out.push_back('\n');
    return out;
}

static const char *kSep = "-----------------------------------------------------------------------------";

static void writeLogFile(Player &p) {
    if (p.logFilename.empty()) {
        p.logFilename = std::to_string(p.id) + "-" + std::to_string(g_startTime) + ".log";
    }
    std::ofstream f(p.logFilename, std::ios::binary | std::ios::trunc);
    if (f) { f << p.log; f.flush(); }
}

// ---------- Main ----------
int main(int argc, char *argv[]) {
    ::signal(SIGPIPE, SIG_IGN);
    g_prog = (argc > 0 && argv[0]) ? argv[0] : "";
    g_startTime = (long long)std::time(nullptr);
    Config cfg = parseArgs(argc, argv);

    std::vector<std::string> commands;
    std::vector<std::string> overrideNames;
    if (cfg.overrideFlag) {
        if (cfg.positional.size() < 4 || (cfg.positional.size() % 2) != 0) {
            std::cout << "Invalid number of player parameters with override switch enabled.  Override intended for server use only.\n";
            std::cout.flush();
            return 1;
        }
        for (size_t i = 0; i < cfg.positional.size(); i += 2) {
            commands.push_back(cfg.positional[i]);
            overrideNames.push_back(cfg.positional[i + 1]);
        }
    } else {
        if (cfg.positional.empty()) {
            std::cout << "Please provide the launch command string for at least one bot.\n";
            std::cout << "Use the --help flag for usage details.\n";
            std::cout.flush();
            return 1;
        }
        commands = cfg.positional;
    }

    // Print bot commands (the original prints each command up to twice).
    for (auto &c : commands) {
        if (!cfg.quiet) std::cout << c << std::endl;
        if (!cfg.overrideFlag) std::cout << c << std::endl;
    }

    int actualPlayers = (int)commands.size();
    int intendedPlayers = (actualPlayers == 1) ? cfg.nplayers : actualPlayers;
    if (actualPlayers > 1 && cfg.nplayers != 1) {
        std::cout << "\nOnly single-player mode enables specified n-player maps.  When entering multiple bots, please do not try to specify n.\n\n";
        std::cout.flush();
        return 1;
    }
    if (intendedPlayers < 1 || intendedPlayers > 6) {
        std::cout << "\nA map can only accommodate between 1 and 6 players.\n\n";
        std::cout.flush();
        return 1;
    }

    // Seed.
    unsigned int actualSeed = cfg.seed;
    if (actualSeed == 0) {
        auto now = std::chrono::system_clock::now();
        long long us = std::chrono::duration_cast<std::chrono::microseconds>(now.time_since_epoch()).count();
        actualSeed = (unsigned int)(us & 0xffffffffLL);
        if (actualSeed == 0) actualSeed = 1;
    }
    // Dimensions.
    int reqW, reqH;
    if (!cfg.dimsSet || (cfg.dims.width == 0 && cfg.dims.height == 0)) {
        static const int choices[] = {20,25,30,35,40,45,50};
        unsigned int pick;
        try {
            std::random_device rd;
            pick = rd();
        } catch (...) {
            pick = (unsigned int)std::chrono::high_resolution_clock::now().time_since_epoch().count();
        }
        reqW = reqH = choices[pick % 7];
    } else {
        // Map dimensions travel through unsigned-short parameters in the original.
        reqW = (int)(unsigned short)cfg.dims.width;
        reqH = (int)(unsigned short)cfg.dims.height;
        // Keep the signed values around for the "both zero" test above; a
        // negative input becomes a very large unsigned-short value here.
        if (cfg.dims.width < 0 || cfg.dims.height < 0 || cfg.dims.width > 65535 || cfg.dims.height > 65535) {
            // These inputs fall into the enormous/huge category handled by
            // the generator's guard (it raises SIGSEGV for >10000).
            reqW = (int)(unsigned short)cfg.dims.width;
            reqH = (int)(unsigned short)cfg.dims.height;
        }
    }

    GeneratedMap gen = generateMap(reqW, reqH, intendedPlayers, actualSeed, actualPlayers);
    GameMap gameMap = gen.map;
    int W = gameMap.W, H = gameMap.H;

    std::cout << W << ' ' << H << std::endl;

    // Replay file.
    bool replayEnabled = !cfg.noreplay;
    std::string replayFilename = std::to_string(g_startTime) + "-" + std::to_string(actualSeed) + ".hlt";
    std::string replayPath;
    std::ofstream replayStream;
    if (replayEnabled) {
        std::string dir = cfg.replayDir;
        if (dir.empty()) replayPath = "/" + replayFilename;
        else if (dir.back() == '/') replayPath = dir + replayFilename;
        else replayPath = dir + "/" + replayFilename;
        replayStream.open(replayPath, std::ios::binary | std::ios::trunc);
        if (!replayStream.is_open() || replayStream.fail()) {
            throw std::runtime_error("Could not open file for replay");
        }
    }

    // Players.
    std::vector<Player> players;
    players.reserve(commands.size());
    for (size_t i = 0; i < commands.size(); ++i) {
        Player p;
        p.id = (int)i + 1;
        p.command = commands[i];
        players.push_back(std::move(p));
    }
    for (auto &p : players) launchBot(p);

    // Init communication in parallel.
    {
        std::vector<std::thread> ths;
        for (size_t i = 0; i < players.size(); ++i) {
            ths.emplace_back([&, i]() {
                Player &p = players[i];
                auto start = std::chrono::steady_clock::now();
                std::string msg;
                msg += std::to_string(p.id) + "\n";
                msg += std::to_string(W) + " " + std::to_string(H) + " \n";
                msg += productionLine(gameMap);
                msg += frameLine(gameMap);
                writeAllFd(p.writeFd, msg);
                if (!cfg.quiet) {
                    std::lock_guard<std::mutex> lock(g_coutMutex);
                    std::cout << "Init Message sent to player " << p.id << ".\n";
                }
                p.log += " --- Init ---\n";
                std::string name;
                BotReader::readLineBlocking(p, name);
                long long used = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
                p.log += name + "\n";
                p.log += " --- Bot used " + std::to_string(used) + " milliseconds ---\n";
                p.log += kSep; p.log += "\n";
                p.botName = truncate30(name);
                if (cfg.overrideFlag) p.finalName = truncate30(overrideNames[i]);
                else p.finalName = p.botName;
                if (!cfg.quiet) {
                    std::lock_guard<std::mutex> lock(g_coutMutex);
                    std::cout << "Init Message received from player " << p.id << ", " << p.botName << ".\n";
                }
            });
        }
        for (auto &t : ths) t.join();
    }

    int maxTurns = (int)(std::sqrt((double)((long long)W * (long long)H)) * 10.0);
    if (maxTurns < 0) maxTurns = 0;

    // Frames / moves for replay.
    std::vector<GameMap> frames;
    frames.push_back(gameMap);
    std::vector<std::vector<std::vector<int>>> allMoves;
    // Statistics for the initial frame.
    for (auto &p : players) {
        int terr = 0;
        for (int o : gameMap.owner) if (o == p.id) ++terr;
        if (terr > 0) p.lastFrameAlive = 0;
        p.totalTerritory += terr;
    }

    auto countTerritory = [&](const GameMap &m, int id) {
        int t = 0; for (int o : m.owner) if (o == id) ++t; return t;
    };

    for (int turn = 1; turn <= maxTurns; ++turn) {
        if (!cfg.quiet) std::cout << "Turn " << turn << "\n";
        // Communication threads for players still in the game.
        std::vector<int> commIdx;
        for (size_t i = 0; i < players.size(); ++i) {
            Player &p = players[i];
            if (p.errored) continue;
            if (countTerritory(gameMap, p.id) <= 0) continue;
            commIdx.push_back((int)i);
        }
        {
            std::vector<std::thread> ths;
            for (int pi : commIdx) {
                ths.emplace_back([&, pi]() {
                    Player &p = players[(size_t)pi];
                    auto start = std::chrono::steady_clock::now();
                    std::string msg = frameLine(gameMap);
                    writeAllFd(p.writeFd, msg);
                    p.log += " --- Frame #" + std::to_string(turn) + " ---\n";
                    BotReader::Outcome out = BotReader::readLineDeadline(p, cfg.ignoreTimeouts ? -1LL : 1500LL, start);
                    long long used = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
                    if (out.success) {
                        p.turnHasResponse = true;
                        p.turnResponse = out.line;
                        p.log += out.line + "\n";
                        p.log += " --- Bot used " + std::to_string(used) + " milliseconds ---\n";
                        bool valid = true;
                        for (unsigned char c : out.line) {
                            if (!((c >= '0' && c <= '9') || c == ' ')) { valid = false; break; }
                        }
                        if (!valid) {
                            p.turnInvalid = true; p.turnError = true;
                            p.log += "ERRORED!\nResponse received (if any):\n" + out.line;
                            if (!cfg.quiet) {
                                std::lock_guard<std::mutex> lock(g_coutMutex);
                                std::cout << "Bot sent an invalid character - ejecting from game.\n";
                            }
                        } else {
                            p.log += kSep; p.log += "\n";
                        }
                    } else {
                        p.turnError = true;
                        p.log += "\nERRORED!\n";
                        if (out.partial.empty()) p.log += "No response received.";
                        else p.log += "Response received (if any):\n" + out.partial;
                        if (!cfg.quiet) {
                            std::lock_guard<std::mutex> lock(g_coutMutex);
                            std::cout << "Bot #" << p.id << " timeout or error (Unix) 0\n";
                        }
                    }
                });
            }
            for (auto &t : ths) t.join();
        }

        // Eject errored players.
        for (auto &p : players) {
            if (p.turnError && !p.errored) {
                p.errored = true;
                writeLogFile(p);
                killBot(p);
                for (int k = 0; k < W * H; ++k) if (gameMap.owner[k] == p.id) gameMap.owner[k] = 0;
            }
            p.turnError = false;
        }

        // Parse moves.
        std::vector<std::vector<int>> moveGrid((size_t)H, std::vector<int>((size_t)W, 0));
        for (auto &p : players) {
            if (p.errored || !p.turnHasResponse || p.turnInvalid) continue;
            // Only players with territory at the start of the turn can move;
            // they were in commIdx or are still recorded by ownership checks below.
            std::stringstream ss(p.turnResponse);
            unsigned short x, y, d;
            while (ss >> x >> y >> d) {
                if (x < W && y < H) {
                    int idxx = cellIndex((int)x, (int)y, W);
                    if (gameMap.owner[idxx] == p.id) {
                        moveGrid[(size_t)y][(size_t)x] = (int)(unsigned char)d;
                    }
                }
            }
            p.turnHasResponse = false;
            p.turnResponse.clear();
            p.turnInvalid = false;
        }

        // Build move direction array.
        std::vector<int> moveDir((size_t)W * H, 0);
        for (int y = 0; y < H; ++y) for (int x = 0; x < W; ++x) moveDir[cellIndex(x,y,W)] = moveGrid[(size_t)y][(size_t)x];

        // --- Process the turn ---
        struct Piece {
            int owner; int strength; int x; int y;
        };
        std::vector<Piece> pieces;
        pieces.reserve((size_t)W * H * 2);
        for (int y = 0; y < H; ++y) {
            for (int x = 0; x < W; ++x) {
                int idxx = cellIndex(x,y,W);
                int owner = gameMap.owner[idxx];
                int strength = gameMap.strength[idxx];
                int dir = (owner != 0) ? moveDir[idxx] : 0;
                if (owner != 0 && dir == 0) {
                    strength = std::min(255, strength + gameMap.production[idxx]);
                }
                int tx = x, ty = y;
                if (owner != 0 && dir != 0) {
                    switch (dir) {
                        case 1: ty = (y - 1 + H) % H; break;
                        case 2: tx = (x + 1) % W; break;
                        case 3: ty = (y + 1) % H; break;
                        case 4: tx = (x - 1 + W) % W; break;
                        default: tx = x; ty = y; break;
                    }
                }
                if (owner != 0 && dir != 0 && (tx != x || ty != y)) {
                    pieces.push_back({owner, 0, x, y});
                    pieces.push_back({owner, strength, tx, ty});
                } else {
                    pieces.push_back({owner, strength, x, y});
                }
            }
        }
        // Group by location and owner.
        struct Group { int owner; int strength; int x; int y; };
        std::vector<Group> groups;
        {
            std::map<std::tuple<int,int,int>, size_t> pos;
            for (auto &pc : pieces) {
                auto key = std::make_tuple(pc.x, pc.y, pc.owner);
                auto it = pos.find(key);
                if (it == pos.end()) {
                    pos[key] = groups.size();
                    groups.push_back({pc.owner, pc.strength, pc.x, pc.y});
                } else {
                    Group &g = groups[it->second];
                    g.strength = std::min(255, g.strength + pc.strength);
                }
            }
        }
        // Combat.
        int G = (int)groups.size();
        std::vector<int> damage((size_t)G, 0);
        std::vector<char> inCombat((size_t)G, 0), dead((size_t)G, 0);
        for (int i = 0; i < G; ++i) {
            for (int j = 0; j < G; ++j) {
                if (i == j) continue;
                if (groups[j].owner == groups[i].owner) continue;
                bool same = (groups[j].x == groups[i].x && groups[j].y == groups[i].y);
                if (same) {
                    damage[i] += groups[j].strength; inCombat[i] = 1;
                } else {
                    if (groups[i].owner == 0 || groups[j].owner == 0) continue;
                    int dx = std::abs(groups[j].x - groups[i].x); dx = std::min(dx, W - dx);
                    int dy = std::abs(groups[j].y - groups[i].y); dy = std::min(dy, H - dy);
                    if ((dx == 1 && dy == 0) || (dx == 0 && dy == 1)) {
                        damage[i] += groups[j].strength; inCombat[i] = 1;
                    }
                }
            }
        }
        GameMap next = gameMap;
        for (int i = 0; i < W * H; ++i) { next.owner[i] = 0; next.strength[i] = 0; }
        for (int i = 0; i < G; ++i) {
            if (inCombat[i] && damage[i] >= groups[i].strength) { dead[i] = 1; continue; }
            int ns = groups[i].strength - (inCombat[i] ? damage[i] : 0);
            if (ns < 0) ns = 0;
            int idxx = cellIndex(groups[i].x, groups[i].y, W);
            next.owner[idxx] = groups[i].owner;
            next.strength[idxx] = ns;
        }
        gameMap = next;
        frames.push_back(gameMap);
        allMoves.push_back(moveGrid);

        int frameIndex = (int)frames.size() - 1;
        for (auto &p : players) {
            int terr = countTerritory(gameMap, p.id);
            if (terr > 0) p.lastFrameAlive = frameIndex;
            p.totalTerritory += terr;
        }

        // Kill bots of players who have just lost their last territory.
        for (auto &p : players) {
            if (!p.errored && p.processRunning && countTerritory(gameMap, p.id) <= 0) {
                // A player with no territory will not be consulted again.
                // (In a one-player game an errored player is already handled;
                // a combat elimination only matters when the game continues.)
                if (actualPlayers > 1) killBot(p);
            }
        }

        // Termination.
        if (actualPlayers > 1) {
            int alive = 0;
            for (auto &p : players) if (countTerritory(gameMap, p.id) > 0) ++alive;
            if (alive <= 1) break;
        } else {
            if (players.size() == 1 && countTerritory(gameMap, players[0].id) >= W * H) break;
        }
    }

    // Kill remaining bots.
    for (auto &p : players) if (p.processRunning) killBot(p);

    // Rankings.
    std::vector<int> order;
    for (size_t i = 0; i < players.size(); ++i) order.push_back((int)i);
    std::sort(order.begin(), order.end(), [&](int a, int b) {
        Player &pa = players[(size_t)a], &pb = players[(size_t)b];
        if (pa.lastFrameAlive != pb.lastFrameAlive) return pa.lastFrameAlive > pb.lastFrameAlive;
        if (pa.totalTerritory != pb.totalTerritory) return pa.totalTerritory > pb.totalTerritory;
        return pa.id > pb.id;
    });
    for (size_t i = 0; i < order.size(); ++i) players[(size_t)order[i]].rank = (int)i + 1;

    // Replay JSON.
    if (replayEnabled) {
        std::string j;
        j += "{\"frames\":[";
        for (size_t fi = 0; fi < frames.size(); ++fi) {
            if (fi) j.push_back(',');
            j.push_back('[');
            for (int y = 0; y < H; ++y) {
                if (y) j.push_back(',');
                j.push_back('[');
                for (int x = 0; x < W; ++x) {
                    if (x) j.push_back(',');
                    int idxx = cellIndex(x,y,W);
                    j += "[" + std::to_string(frames[fi].owner[idxx]) + "," + std::to_string(frames[fi].strength[idxx]) + "]";
                }
                j.push_back(']');
            }
            j.push_back(']');
        }
        j += "],\"height\":" + std::to_string(H);
        j += ",\"moves\":[";
        for (size_t mi = 0; mi < allMoves.size(); ++mi) {
            if (mi) j.push_back(',');
            j.push_back('[');
            for (int y = 0; y < H; ++y) {
                if (y) j.push_back(',');
                j.push_back('[');
                for (int x = 0; x < W; ++x) {
                    if (x) j.push_back(',');
                    j += std::to_string(allMoves[mi][(size_t)y][(size_t)x]);
                }
                j.push_back(']');
            }
            j.push_back(']');
        }
        j += "],\"num_frames\":" + std::to_string(frames.size());
        j += ",\"num_players\":" + std::to_string(players.size());
        j += ",\"player_names\":[";
        for (size_t i = 0; i < players.size(); ++i) {
            if (i) j.push_back(',');
            j.push_back('"'); j += jsonEscape(players[i].finalName); j.push_back('"');
        }
        j += "],\"productions\":[";
        for (int y = 0; y < H; ++y) {
            if (y) j.push_back(',');
            j.push_back('[');
            for (int x = 0; x < W; ++x) {
                if (x) j.push_back(',');
                j += std::to_string(gameMap.production[cellIndex(x,y,W)]);
            }
            j.push_back(']');
        }
        j += "],\"version\":11,\"width\":" + std::to_string(W) + "}";
        replayStream << j;
        replayStream.flush();
        replayStream.close();
    }

    // Final output.
    if (cfg.quiet) {
        if (replayEnabled) std::cout << replayPath << ' ' << actualSeed << '\n';
        for (auto &p : players) {
            std::cout << p.id << ' ' << p.rank << ' ' << p.lastFrameAlive << '\n';
        }
        std::string ids, logs;
        for (auto &p : players) if (p.errored) {
            if (!ids.empty()) ids.push_back(' ');
            ids += std::to_string(p.id);
            if (!logs.empty()) logs.push_back(' ');
            logs += p.logFilename;
        }
        std::cout << ids << " \n" << logs << " ";
    } else {
        if (replayEnabled) {
            std::cout << "Map seed was " << actualSeed << '\n';
            std::cout << "Opening a file at " << replayPath << '\n';
        }
        for (auto &p : players) {
            std::cout << "Player #" << p.id << ", " << p.finalName << ", came in rank #" << p.rank << " and was last alive on frame #" << p.lastFrameAlive << "!\n";
        }
    }
    std::cout.flush();
    return 0;
}
