from mt import MT

def draws(seed,n=2000):
    mt=MT(seed); return [mt.gen() for _ in range(n)]

def find_subseq(final, transform, seed, maxoff=500):
    d=draws(seed, maxoff+len(final)+10)
    vals=[transform(x) for x in d]
    res=[]
    for off in range(maxoff):
